# Split and write part files
for part in range(1, 5):
    p_path = os.path.join(HERE, f"batch_part{part}.json")
    if not os.path.exists(p_path):
        continue
    part_keys = json.load(open(p_path, encoding="utf-8")).keys()
    part_trans = {k: trans[k] for k in part_keys if k in trans}
    out_path = os.path.join(HERE, f"trans_part_{part}.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(part_trans, f, ensure_ascii=False, indent=2)
    print(f"Wrote {out_path} with {len(part_trans)} keys")
